import {emptyBoard,applyPair,pairCount,coord} from './engine.js?v=9';
import {bookChildren,lookupBook,bookStats,packBook,mergeBook} from './book.js?v=9';
const $=id=>document.getElementById(id);
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('gomulda-book',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function readDB(db){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('book');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function writeDB(db,value,key='book'){return new Promise((resolve,reject)=>{const t=db.transaction('state','readwrite');t.objectStore('state').put(value,key);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}
export async function initBookLab({currentPosition}){
 let book=null,db=null,worker=null,busy=false,ready=false,study=emptyBoard(),path=[],message='Loading and checking the book…',saveQueue=Promise.resolve(),ruleWarning='';
 const describe=e=>e?.exact?`Proven ${e.lower}`:e?(e.lower>0||e.upper<book.cap?`Proven bound ${e.lower}–${e.upper===book.cap?'?':e.upper}`:'Unsolved'):'Unexamined';
 function draw(){
  $('book-status').textContent=ruleWarning?`${ruleWarning} ${message}`:message;for(const id of ['book-analyze','book-grow','book-import','book-export','book-time','book-lines'])$(id).disabled=!ready||busy;$('book-stop').hidden=!busy;$('book-stop').disabled=false;if(!book)return;
  const stats=bookStats(book);$('book-counts').textContent=`${stats.positions.toLocaleString()} stored positions · ${stats.solved.toLocaleString()} solved pairing positions · ${stats.terminals.toLocaleString()} solved final maps · ${stats.estimates.toLocaleString()} estimates`;
  const root=lookupBook(book,emptyBoard());$('book-root-status').textContent=`Initial value: ${root?.exact?root.lower:'not proven'}. Sixth-colour cost: ${book.extraCost}.`;
  const n=pairCount(study),e=lookupBook(book,study);$('book-position-title').textContent=n===12?'Completed map':`${n===0?'Initial position':`${n} pairs placed`} · ${n%2===0?'White':'Black'} to pair`;
  $('book-position-value').textContent=describe(e);$('book-back').disabled=!path.length;$('book-board').replaceChildren(...study.map((c,i)=>{const cell=document.createElement('span');cell.textContent=c<0?'·':c;cell.className=c<0?'empty':'';cell.title=`${coord(i)}${c<0?' · unused':` · country ${c}`}`;return cell;}));
  const recommendation=e?.exact?e.move:e?.analysis?.move;$('book-follow').disabled=!recommendation;$('book-suggestion').textContent=recommendation?`${e.exact?'Proven optimal pair':'Stored search suggestion'}: ${recommendation.map(coord).join(' + ')}.${e.exact?'':` Estimated penalty ${e.analysis.value.toFixed(2)} from ${(e.analysis.timeMs/1000).toFixed(2)} s of Search.`}`:'Analyse this position to add a search suggestion or a proof.';
  const rows=bookChildren(study);$('book-coverage').textContent=`${rows.filter(c=>book.entries[c.key]).length} of ${rows.length} distinct continuations stored. Rotations, reflections and pairing order share one entry.`;
  const body=$('book-rows');body.replaceChildren();for(const c of rows){const child=lookupBook(book,c.board),row=document.createElement('tr'),pair=document.createElement('td'),button=document.createElement('button');button.className='text-button';button.textContent=c.move.map(coord).join(' + ');button.setAttribute('aria-label',`Study ${button.textContent}`);button.onclick=()=>{path.push(study);study=applyPair(study,c.move);draw();};pair.append(button);const value=document.createElement('td');value.textContent=child?.exact?child.lower:child?.analysis?`≈ ${child.analysis.value.toFixed(2)}`:'—';const evidence=document.createElement('td');evidence.textContent=describe(child);if(child?.analysis&&!child.exact)evidence.textContent+=' · search estimate';row.append(pair,value,evidence);body.append(row);}
 }
 function persist(){if(!db){message='Book changes are in memory. Export the book to keep them.';draw();return;}const raw=packBook(book);saveQueue=saveQueue.then(()=>writeDB(db,raw)).catch(()=>{message='Local saving failed. Export the book to keep your work.';draw();});}
 function run(command,raw,replace=false){if(busy)throw Error('A book job is already running.');busy=true;draw();return new Promise((resolve,reject)=>{
  worker=new Worker(new URL('./book-worker.js?v=9',import.meta.url),{type:'module'});const finish=()=>{busy=false;worker.terminate();worker=null;draw();};
  worker.onerror=()=>{message='Book analysis stopped unexpectedly. Previously saved work is retained.';finish();reject(Error(message));};
  worker.onmessage=({data})=>{try{if(data.book){book=!book||replace?data.book:mergeBook(book,data.book);if(command!=='load')persist();}if(data.kind==='progress'){message=`${data.completed}/${data.total} ${command==='grow'?'book lines':'positions'} analysed. Completed results are saved.`;draw();}else if(data.kind==='done'){message=command==='load'?'Book checked. Exact values follow from verified colouring results and minimax bounds.':data.stopped?'Stopped. Completed book work is saved.':'Book analysis complete. Estimates and proofs are shown separately.';finish();resolve(book);}else if(data.kind==='error'){message=data.error;finish();reject(Error(message));}}catch(e){message=e.message;finish();reject(e);}};
  worker.postMessage({command,book:raw??packBook(book),board:study,timeMs:Number($('book-time').value),lines:Number($('book-lines').value)});
 });}
 const launch=command=>{message=command==='grow'?'Exploring another opening and its continuations…':'Analysing this position…';return run(command).catch(()=>{});};
 $('book-analyze').onclick=()=>launch('analyze');$('book-grow').onclick=()=>launch('grow');$('book-stop').onclick=()=>{worker?.postMessage({command:'stop'});$('book-stop').disabled=true;message='Stopping after the current position or book line…';$('book-status').textContent=message;};
 $('book-example').onclick=()=>{const e=Object.values(book?.entries??{}).filter(e=>e.ply<12&&e.lower===e.upper).sort((a,b)=>a.ply-b.ply)[0];if(e){study=e.board.slice();path=[];draw();}};
 $('book-follow').onclick=()=>{const e=lookupBook(book,study),move=e?.exact?e.move:e?.analysis?.move;if(move){path.push(study);study=applyPair(study,move);draw();}};
 $('book-back').onclick=()=>{if(path.length)study=path.pop();draw();};$('book-start').onclick=()=>{study=emptyBoard();path=[];draw();};$('book-current').onclick=()=>{const p=currentPosition();if(p.extraCost!==book?.extraCost){message='This book uses different colour costs from the current match.';draw();return;}study=p.board.slice();path=[];draw();};
 $('book-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(packBook(book))],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`gomulda-book-${book.size}-positions.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('book-import').onchange=async()=>{try{const f=$('book-import').files[0];if(!f)return;if(f.size>30*1024*1024)throw Error('Book is too large (maximum 30 MB).');message='Checking imported positions and recomputing proofs…';await run('load',JSON.parse(await f.text()),true);study=emptyBoard();path=[];persist();draw();}catch(e){message=e.message;draw();}finally{$('book-import').value='';}};
 try{db=await openDB();const saved=await readDB(db);if(saved){if(saved.extraCost!==25){await writeDB(db,saved,'before-fixed-rule');ruleWarning='Your book used older custom colour costs and was backed up on this device. Using the fixed-rule book.';}else await run('load',saved,true);}}catch(e){message=`Saved book could not be loaded: ${e.message}`;}
 if(!book){const response=await fetch('./book-seed.json');if(!response.ok)throw Error('The initial book could not be loaded.');await run('load',await response.json(),true);}
 ready=true;draw();return {getBook(extraCost){if(!ready)throw Error('The book is still loading.');if(book.extraCost!==extraCost)throw Error(`Search + book uses sixth-colour cost ${book.extraCost}. Import a book for the fixed cost of 25.`);return packBook(book);},accept(updated){try{book=mergeBook(book,updated);persist();}catch(e){message=`The move was played, but its book update could not be saved: ${e.message}`;}draw();},read(){return {ready,busy,...bookStats(book),study:study.slice(),position:describe(lookupBook(book,study))};},grow(lines=1){if(busy)throw Error('A book job is already running.');if(![1,5,20].includes(lines))throw Error('Choose 1, 5 or 20 book lines.');$('book-lines').value=String(lines);launch('grow');return {started:busy};}};
}
